START TRANSACTION;
CREATE TABLE "Conversations" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
    "UserId" text NOT NULL,
    "Title" text NOT NULL,
    "CreatedUtc" timestamp without time zone NOT NULL,
    "UpdatedUtc" timestamp without time zone NOT NULL,
    CONSTRAINT "PK_Conversations" PRIMARY KEY ("Id")
);

CREATE TABLE "Turns" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
    "ConversationId" bigint NOT NULL,
    "Index" integer NOT NULL,
    "Question" text NOT NULL,
    "Answer" text NOT NULL,
    "RetrievedChunkIds" text[] NOT NULL,
    "CreatedUtc" timestamp without time zone NOT NULL,
    CONSTRAINT "PK_Turns" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Turns_Conversations_ConversationId" FOREIGN KEY ("ConversationId") REFERENCES "Conversations" ("Id") ON DELETE CASCADE
);

CREATE TABLE "Feedbacks" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
    "TurnId" bigint NOT NULL,
    "Value" integer NOT NULL,
    "SetUtc" timestamp without time zone NOT NULL,
    CONSTRAINT "PK_Feedbacks" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Feedbacks_Turns_TurnId" FOREIGN KEY ("TurnId") REFERENCES "Turns" ("Id") ON DELETE CASCADE
);

CREATE UNIQUE INDEX "IX_Feedbacks_TurnId" ON "Feedbacks" ("TurnId");

CREATE INDEX "IX_Turns_ConversationId" ON "Turns" ("ConversationId");

